// src/pages/ResultPage.jsx
import React from "react";
import { useLocation, useNavigate } from "react-router-dom";

function ResultPage() {
  const location = useLocation();
  const navigate = useNavigate();

  const {
    symptoms = [],
    predictions = [],
    symptom_details = [], // 👈 include details
  } = location.state || {};

  return (
    <div className="result-container">
      <h2>🩺 Health Summary</h2>
      <p>Here’s what we found based on your symptoms.</p>

      {/* ─────────────────────────────── */}
      {/* Detected Symptoms with Details */}
      {/* ─────────────────────────────── */}
      <div className="result-section">
        <h3>Detected Symptoms:</h3>
        {symptom_details.length > 0 ? (
          <ul className="symptom-list">
            {symptom_details.map((s, i) => (
              <li key={i} className="symptom-item">
                <strong>{s.symptom}</strong>
                <p className="desc">
                  <b>Description:</b> {s.description}
                </p>
                <p className="desc">
                  <b>Common causes:</b> {s.common_causes}
                </p>
                <p className="desc">
                  <b>Advice:</b> {s.advice}
                </p>
              </li>
            ))}
          </ul>
        ) : (
          <ul>
            {symptoms.map((s, i) => (
              <li key={i}>{s}</li>
            ))}
          </ul>
        )}
      </div>

      {/* ─────────────────────────────── */}
      {/* Predicted Diseases */}
      {/* ─────────────────────────────── */}
      <div className="result-section">
        <h3>Possible Conditions:</h3>
        <ul>
          {predictions.map((p, i) => (
            <li key={i}>
              <b>{p.disease}</b> — confidence: {Math.round(p.score * 100)}%
            </li>
          ))}
        </ul>
      </div>

      <button onClick={() => navigate("/")} className="btn-back">
        Back to Chat
      </button>
    </div>
  );
}

export default ResultPage;
